static void printTree(Path root) throws IOException {
    try (Stream<Path> walk = Files.walk(root)) {
        walk.sorted().forEach(p -> {
            int glebokosc = root.relativize(p).getNameCount();
            System.out.println("  ".repeat(glebokosc) + p.getFileName());
        });
    }
}

static Map<String, List<Path>> findDuplicates(Path root) throws IOException {
    try (Stream<Path> walk = Files.walk(root)) {
        return walk.filter(Files::isRegularFile)
            .collect(Collectors.groupingBy(p -> {
                try {
                    return new String(Files.readAllBytes(p));
                } catch (IOException e) { return ""; }
            }));
    }
}

static void backup(Path source, Path targetBackupDir) throws IOException {
    try (Stream<Path> walk = Files.walk(source)) {
        for (Path p : (Iterable<Path>) walk::iterator) {
            Path relative = source.relativize(p);
            Path target = targetBackupDir.resolve(relative);
            if (Files.isDirectory(p)) {
                Files.createDirectories(target);
            } else {
                Files.createDirectories(target.getParent());
                Files.copy(p, target, StandardCopyOption.REPLACE_EXISTING);
            }
        }
    }
}

static void rotate(Path logFile, int maxBackups) throws IOException {
    for (int i = maxBackups - 1; i >= 1; i--) {
        Path from = logFile.resolveSibling(logFile.getFileName() + "." + i);
        Path to = logFile.resolveSibling(logFile.getFileName() + "." + (i + 1));
        if (Files.exists(from)) {
            Files.move(from, to, StandardCopyOption.REPLACE_EXISTING);
        }
    }
    Path firstBackup = logFile.resolveSibling(logFile.getFileName() + ".1");
    if (Files.exists(logFile)) {
        Files.move(logFile, firstBackup, StandardCopyOption.REPLACE_EXISTING);
    }
    Files.createFile(logFile);
}

