static List<Path> findFilesLargerThan(Path root, long minBytes) throws IOException {
    try (Stream<Path> walk = Files.walk(root)) {
        return walk.filter(Files::isRegularFile)
            .filter(p -> {
                try { return Files.size(p) > minBytes; } catch (IOException e) { return false; }
            })
            .toList();
    }
}

static void sync(Path source, Path target) throws IOException {
    try (Stream<Path> lista = Files.list(source)) {
        for (Path p : (Iterable<Path>) lista::iterator) {
            Path docelowy = target.resolve(p.getFileName());
            boolean rozne = !Files.exists(docelowy)
                || !Arrays.equals(Files.readAllBytes(p), Files.readAllBytes(docelowy));
            if (rozne) {
                Files.copy(p, docelowy, StandardCopyOption.REPLACE_EXISTING);
            }
        }
    }
}

static class TempWorkspace {
    private Path dir;

    void setup() throws IOException {
        dir = Files.createTempDirectory("workspace_");
    }

    void addFile(String name, String content) throws IOException {
        Files.writeString(dir.resolve(name), content);
    }

    List<String> listFiles() throws IOException {
        try (Stream<Path> lista = Files.list(dir)) {
            return lista.map(p -> p.getFileName().toString()).toList();
        }
    }

    void cleanup() throws IOException {
        try (Stream<Path> walk = Files.walk(dir)) {
            walk.sorted(Comparator.reverseOrder()).forEach(p -> {
                try { Files.delete(p); } catch (IOException e) { }
            });
        }
    }
}

static void mergeCsvFiles(Path dir, Path outputFile) throws IOException {
    List<Path> csvPliki;
    try (Stream<Path> walk = Files.walk(dir)) {
        csvPliki = walk.filter(p -> p.toString().endsWith(".csv")).sorted().toList();
    }
    List<String> wynik = new ArrayList<>();
    boolean pierwszy = true;
    for (Path p : csvPliki) {
        List<String> linie = Files.readAllLines(p);
        if (pierwszy) {
            wynik.add(linie.get(0)); // naglowek
            pierwszy = false;
        }
        wynik.addAll(linie.subList(1, linie.size()));
    }
    Files.write(outputFile, wynik);
}

static void archiveOlderThan(Path dir, int year) throws IOException {
    Path archiwum = dir.resolve("archiwum");
    Files.createDirectories(archiwum);
    try (Stream<Path> lista = Files.list(dir)) {
        for (Path p : (Iterable<Path>) lista::iterator) {
            if (!Files.isRegularFile(p)) continue;
            java.util.regex.Matcher m = java.util.regex.Pattern.compile("\\d{4}").matcher(p.getFileName().toString());
            if (m.find() && Integer.parseInt(m.group()) < year) {
                Files.move(p, archiwum.resolve(p.getFileName()));
            }
        }
    }
}
